import{E as e,d as t,l as n}from"./runtime-core.esm-bundler-tCF-J6l5.js";import{t as r}from"./app-DkHKZVQg.js";var i=JSON.parse(`{"path":"/%E5%90%8E%E7%AB%AF%E5%BC%80%E5%8F%91/ASP.NET_Core/SQL%E7%9F%A5%E8%AF%86%E5%BA%93/01_%E6%9F%A5%E8%AF%A2%E8%BF%9B%E9%98%B6/02.CTE%E4%B8%8E%E9%80%92%E5%BD%92%E6%9F%A5%E8%AF%A2.html","title":"CTE 与递归查询","lang":"zh-CN","frontmatter":{"title":"CTE 与递归查询","category":["SQL Server"],"tag":["SQL知识库","查询进阶"],"order":2},"git":{"createdTime":1776135420000,"updatedTime":1776135420000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":5.65,"words":1696},"filePathRelative":"后端开发/ASP.NET_Core/SQL知识库/01_查询进阶/02.CTE与递归查询.md"}`),a={name:`02.CTE与递归查询.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="cte-与递归查询" tabindex="-1"><a class="header-anchor" href="#cte-与递归查询"><span>CTE 与递归查询</span></a></h1><p>CTE（Common Table Expression，公用表表达式）说白了就是给子查询起个名字，让 SQL 更好读。但它真正厉害的地方在于递归——处理树形结构数据的时候，没有比它更方便的了。</p><h2 id="基本-cte" tabindex="-1"><a class="header-anchor" href="#基本-cte"><span>基本 CTE</span></a></h2><h3 id="语法" tabindex="-1"><a class="header-anchor" href="#语法"><span>语法</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> cte名 </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> ...</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> cte名;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>那个开头的分号是个好习惯——避免前面的语句没写分号导致语法报错。</p><h3 id="和子查询有什么区别" tabindex="-1"><a class="header-anchor" href="#和子查询有什么区别"><span>和子查询有什么区别</span></a></h3><p>功能上没区别，CTE 就是让 SQL 更好看。对比一下：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 子查询写法：嵌套一层套一层，看着头疼</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#D19A66;"> d</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">DeptName</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">t</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">AvgSalary</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> DeptId, </span><span style="color:#56B6C2;">AVG</span><span style="color:#ABB2BF;">(Salary) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> AvgSalary</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Employees</span></span>
<span class="line"><span style="color:#C678DD;">    GROUP BY</span><span style="color:#ABB2BF;"> DeptId</span></span>
<span class="line"><span style="color:#ABB2BF;">) t</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#ABB2BF;"> Departments d </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> d</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Id</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> t</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">DeptId</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#D19A66;"> t</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">AvgSalary</span><span style="color:#56B6C2;"> &gt;</span><span style="color:#D19A66;"> 10000</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- CTE 写法：逻辑一块一块的，清清楚楚</span></span>
<span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> DeptAvg </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> DeptId, </span><span style="color:#56B6C2;">AVG</span><span style="color:#ABB2BF;">(Salary) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> AvgSalary</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Employees</span></span>
<span class="line"><span style="color:#C678DD;">    GROUP BY</span><span style="color:#ABB2BF;"> DeptId</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#D19A66;"> d</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">DeptName</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">da</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">AvgSalary</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> DeptAvg da</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#ABB2BF;"> Departments d </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> d</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Id</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> da</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">DeptId</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#D19A66;"> da</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">AvgSalary</span><span style="color:#56B6C2;"> &gt;</span><span style="color:#D19A66;"> 10000</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="多个-cte-串联" tabindex="-1"><a class="header-anchor" href="#多个-cte-串联"><span>多个 CTE 串联</span></a></h3><p>一个 WITH 后面可以跟多个 CTE，用逗号隔开：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span></span>
<span class="line"><span style="color:#ABB2BF;">Step1 </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> DeptId, </span><span style="color:#56B6C2;">COUNT</span><span style="color:#ABB2BF;">(*) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> EmpCount</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Employees</span></span>
<span class="line"><span style="color:#C678DD;">    GROUP BY</span><span style="color:#ABB2BF;"> DeptId</span></span>
<span class="line"><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">Step2 </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> DeptId, </span><span style="color:#56B6C2;">SUM</span><span style="color:#ABB2BF;">(Amount) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> TotalSales</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Sales</span></span>
<span class="line"><span style="color:#C678DD;">    GROUP BY</span><span style="color:#ABB2BF;"> DeptId</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#D19A66;"> s1</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">DeptId</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">s1</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">EmpCount</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">s2</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">TotalSales</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#D19A66;">    s2</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">TotalSales</span><span style="color:#ABB2BF;"> / </span><span style="color:#D19A66;">s1</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">EmpCount</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> SalesPerPerson</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Step1 s1</span></span>
<span class="line"><span style="color:#C678DD;">JOIN</span><span style="color:#ABB2BF;"> Step2 s2 </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> s1</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">DeptId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> s2</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">DeptId</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>把复杂查询拆成几步，每步一个 CTE，最后组装。比嵌套三四层子查询好理解太多了。</p><h3 id="cte-能做-dml" tabindex="-1"><a class="header-anchor" href="#cte-能做-dml"><span>CTE 能做 DML</span></a></h3><p>这是很多人不知道的——CTE 可以直接 UPDATE、DELETE：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 删除每个部门工资最低的人</span></span>
<span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> cte </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> *,</span></span>
<span class="line"><span style="color:#56B6C2;">        ROW_NUMBER</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;"> (</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> DeptId </span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Salary) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> rn</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Employees</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">DELETE</span><span style="color:#C678DD;"> FROM</span><span style="color:#ABB2BF;"> cte </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> rn </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 更新也行</span></span>
<span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> cte </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> *, </span><span style="color:#56B6C2;">ROW_NUMBER</span><span style="color:#ABB2BF;">() </span><span style="color:#C678DD;">OVER</span><span style="color:#ABB2BF;"> (</span><span style="color:#C678DD;">PARTITION</span><span style="color:#C678DD;"> BY</span><span style="color:#ABB2BF;"> Phone </span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> Id </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> rn</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Customers</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">UPDATE</span><span style="color:#ABB2BF;"> cte </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> IsLatest </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> WHERE</span><span style="color:#ABB2BF;"> rn </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="递归-cte" tabindex="-1"><a class="header-anchor" href="#递归-cte"><span>递归 CTE</span></a></h2><p>递归 CTE 是处理树形/层级数据的利器。组织架构、菜单树、分类层级、BOM 物料清单，全靠它。</p><h3 id="结构" tabindex="-1"><a class="header-anchor" href="#结构"><span>结构</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> cte </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 锚点（初始行，起点）</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> Id, ParentId, </span><span style="color:#C678DD;">Name</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">0</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> Level</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Categories</span></span>
<span class="line"><span style="color:#C678DD;">    WHERE</span><span style="color:#ABB2BF;"> ParentId </span><span style="color:#C678DD;">IS</span><span style="color:#C678DD;"> NULL</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    UNION ALL</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    -- 递归部分（每次拿上一层的结果，去找下一层）</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#D19A66;"> c</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Id</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">c</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ParentId</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">c</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Name</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">cte</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Level</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">1</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Categories c</span></span>
<span class="line"><span style="color:#C678DD;">    JOIN</span><span style="color:#ABB2BF;"> cte </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> c</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ParentId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> cte</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Id</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> cte;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>执行过程</strong>：</p><ol><li>先跑锚点查询，拿到根节点</li><li>用根节点的结果去跑递归部分，找到下一层子节点</li><li>再用子节点的结果继续递归，找到孙节点</li><li>直到递归部分查不出新行为止</li></ol><h3 id="实战-组织架构树" tabindex="-1"><a class="header-anchor" href="#实战-组织架构树"><span>实战：组织架构树</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 建表</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#ABB2BF;"> #Org (</span></span>
<span class="line"><span style="color:#ABB2BF;">    Id </span><span style="color:#C678DD;">INT</span><span style="color:#C678DD;"> PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    Name</span><span style="color:#C678DD;"> NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">50</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">    ParentId </span><span style="color:#C678DD;">INT</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    Position </span><span style="color:#C678DD;">NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">50</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#ABB2BF;"> #Org </span><span style="color:#C678DD;">VALUES</span></span>
<span class="line"><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;张总&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;CEO&#39;</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;李副总&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;VP&#39;</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;王经理&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;VP&#39;</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">4</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;赵主管&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;主管&#39;</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;钱主管&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;主管&#39;</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">6</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;孙组长&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">4</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;组长&#39;</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">7</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;周员工&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">6</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;开发&#39;</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">8</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;吴员工&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">6</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;开发&#39;</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">9</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;郑经理&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;主管&#39;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查整棵树，带层级和路径</span></span>
<span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> OrgTree </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> Id, </span><span style="color:#C678DD;">Name</span><span style="color:#ABB2BF;">, ParentId, Position,</span></span>
<span class="line"><span style="color:#D19A66;">        0</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> Level</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#56B6C2;">        CAST</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">Name</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">500</span><span style="color:#ABB2BF;">)) </span><span style="color:#C678DD;">AS</span><span style="color:#C678DD;"> Path</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> #Org</span></span>
<span class="line"><span style="color:#C678DD;">    WHERE</span><span style="color:#ABB2BF;"> ParentId </span><span style="color:#C678DD;">IS</span><span style="color:#C678DD;"> NULL</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    UNION ALL</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#D19A66;"> o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Id</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Name</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ParentId</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Position</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#D19A66;">        t</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Level</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#56B6C2;">        CAST</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">t</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Path</span><span style="color:#ABB2BF;"> + </span><span style="color:#98C379;">&#39; &gt; &#39;</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Name</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> NVARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">500</span><span style="color:#ABB2BF;">))</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> #Org o</span></span>
<span class="line"><span style="color:#C678DD;">    JOIN</span><span style="color:#ABB2BF;"> OrgTree t </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ParentId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> t</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Id</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span></span>
<span class="line"><span style="color:#56B6C2;">    REPLICATE</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;  &#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">Level</span><span style="color:#ABB2BF;">) + </span><span style="color:#C678DD;">Name</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> OrgChart,</span></span>
<span class="line"><span style="color:#ABB2BF;">    Position, </span><span style="color:#C678DD;">Level</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">Path</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> OrgTree</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#C678DD;"> Path</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>结果大概长这样：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>张总              CEO    0  张总</span></span>
<span class="line"><span>  李副总          VP     1  张总 &gt; 李副总</span></span>
<span class="line"><span>    赵主管        主管   2  张总 &gt; 李副总 &gt; 赵主管</span></span>
<span class="line"><span>      孙组长      组长   3  张总 &gt; 李副总 &gt; 赵主管 &gt; 孙组长</span></span>
<span class="line"><span>        周员工    开发   4  张总 &gt; 李副总 &gt; 赵主管 &gt; 孙组长 &gt; 周员工</span></span>
<span class="line"><span>        吴员工    开发   4  张总 &gt; 李副总 &gt; 赵主管 &gt; 孙组长 &gt; 吴员工</span></span>
<span class="line"><span>    钱主管        主管   2  张总 &gt; 李副总 &gt; 钱主管</span></span>
<span class="line"><span>  王经理          VP     1  张总 &gt; 王经理</span></span>
<span class="line"><span>    郑经理        主管   2  张总 &gt; 王经理 &gt; 郑经理</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="实战-查某个节点的所有上级" tabindex="-1"><a class="header-anchor" href="#实战-查某个节点的所有上级"><span>实战：查某个节点的所有上级</span></a></h3><p>反过来查也行——从子节点往上找：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 查 &quot;周员工&quot; 的所有上级</span></span>
<span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> UpTree </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> Id, </span><span style="color:#C678DD;">Name</span><span style="color:#ABB2BF;">, ParentId, </span><span style="color:#D19A66;">0</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> Level</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> #Org</span></span>
<span class="line"><span style="color:#C678DD;">    WHERE</span><span style="color:#C678DD;"> Name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> N&#39;周员工&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    UNION ALL</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#D19A66;"> o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Id</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Name</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ParentId</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">t</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Level</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">1</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> #Org o</span></span>
<span class="line"><span style="color:#C678DD;">    JOIN</span><span style="color:#ABB2BF;"> UpTree t </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Id</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> t</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ParentId</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> UpTree;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 周员工 → 孙组长 → 赵主管 → 李副总 → 张总</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="实战-查某个节点的所有下属" tabindex="-1"><a class="header-anchor" href="#实战-查某个节点的所有下属"><span>实战：查某个节点的所有下属</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 查 &quot;李副总&quot; 下面所有人</span></span>
<span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> DownTree </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> Id, </span><span style="color:#C678DD;">Name</span><span style="color:#ABB2BF;">, ParentId</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> #Org </span><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> Name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> N&#39;李副总&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    UNION ALL</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#D19A66;"> o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Id</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Name</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ParentId</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> #Org o</span></span>
<span class="line"><span style="color:#C678DD;">    JOIN</span><span style="color:#ABB2BF;"> DownTree t </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> o</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ParentId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> t</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Id</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> DownTree;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 李副总、赵主管、钱主管、孙组长、周员工、吴员工</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="实战-生成连续日期" tabindex="-1"><a class="header-anchor" href="#实战-生成连续日期"><span>实战：生成连续日期</span></a></h3><p>递归 CTE 不只是做树形查询，生成序列也好用：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 生成 2024 年 1 月的每一天</span></span>
<span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> Dates </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#56B6C2;"> CAST</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;2024-01-01&#39;</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> DATE</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> dt</span></span>
<span class="line"><span style="color:#C678DD;">    UNION ALL</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#56B6C2;"> DATEADD</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">DAY</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, dt)</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Dates</span></span>
<span class="line"><span style="color:#C678DD;">    WHERE</span><span style="color:#ABB2BF;"> dt </span><span style="color:#56B6C2;">&lt;</span><span style="color:#98C379;"> &#39;2024-01-31&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> dt </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Dates</span></span>
<span class="line"><span style="color:#C678DD;">OPTION</span><span style="color:#ABB2BF;"> (MAXRECURSION </span><span style="color:#D19A66;">31</span><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>用来填充日历表、补全缺失日期都很方便。</p><h3 id="实战-数字序列" tabindex="-1"><a class="header-anchor" href="#实战-数字序列"><span>实战：数字序列</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 生成 1 到 100</span></span>
<span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> Nums </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> n</span></span>
<span class="line"><span style="color:#C678DD;">    UNION ALL</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> n + </span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> FROM</span><span style="color:#ABB2BF;"> Nums </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> n </span><span style="color:#56B6C2;">&lt;</span><span style="color:#D19A66;"> 100</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> n </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> Nums</span></span>
<span class="line"><span style="color:#C678DD;">OPTION</span><span style="color:#ABB2BF;"> (MAXRECURSION </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="maxrecursion-防无限循环" tabindex="-1"><a class="header-anchor" href="#maxrecursion-防无限循环"><span>MAXRECURSION 防无限循环</span></a></h2><p>递归 CTE 默认最多递归 100 次。超过了就报错，防止你写了个死循环把服务器搞挂：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 改成最多 500 次</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> cte </span><span style="color:#C678DD;">OPTION</span><span style="color:#ABB2BF;"> (MAXRECURSION </span><span style="color:#D19A66;">500</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 不限制（慎用！）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> cte </span><span style="color:#C678DD;">OPTION</span><span style="color:#ABB2BF;"> (MAXRECURSION </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果你的树超过 100 层（什么架构能有这么深？），要么是数据有环（A 的父节点是 B，B 的父节点又是 A），要么是你在生成序列忘了设限制。</p><h3 id="检测数据有没有环" tabindex="-1"><a class="header-anchor" href="#检测数据有没有环"><span>检测数据有没有环</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> cte </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> Id, ParentId, </span><span style="color:#56B6C2;">CAST</span><span style="color:#ABB2BF;">(Id </span><span style="color:#C678DD;">AS</span><span style="color:#C678DD;"> VARCHAR</span><span style="color:#ABB2BF;">(MAX)) </span><span style="color:#C678DD;">AS</span><span style="color:#C678DD;"> Path</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Categories </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> ParentId </span><span style="color:#C678DD;">IS</span><span style="color:#C678DD;"> NULL</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    UNION ALL</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#D19A66;"> c</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Id</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">c</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ParentId</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#D19A66;">        cte</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Path</span><span style="color:#ABB2BF;"> + </span><span style="color:#98C379;">&#39;,&#39;</span><span style="color:#ABB2BF;"> + </span><span style="color:#56B6C2;">CAST</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">c</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Id</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">))</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> Categories c</span></span>
<span class="line"><span style="color:#C678DD;">    JOIN</span><span style="color:#ABB2BF;"> cte </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> c</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ParentId</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> cte</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Id</span></span>
<span class="line"><span style="color:#C678DD;">    WHERE</span><span style="color:#D19A66;"> cte</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Path</span><span style="color:#C678DD;"> NOT</span><span style="color:#C678DD;"> LIKE</span><span style="color:#98C379;"> &#39;%&#39;</span><span style="color:#ABB2BF;"> + </span><span style="color:#56B6C2;">CAST</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">c</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Id</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">)) + </span><span style="color:#98C379;">&#39;%&#39;</span><span style="color:#7F848E;font-style:italic;">  -- 已经在路径里了就不再走</span></span>
<span class="line"><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> cte </span><span style="color:#C678DD;">OPTION</span><span style="color:#ABB2BF;"> (MAXRECURSION </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="cte-vs-临时表-vs-表变量" tabindex="-1"><a class="header-anchor" href="#cte-vs-临时表-vs-表变量"><span>CTE vs 临时表 vs 表变量</span></a></h2><table><thead><tr><th></th><th>CTE</th><th>临时表 #t</th><th>表变量 @t</th></tr></thead><tbody><tr><td>作用范围</td><td>紧跟着的 <strong>一条</strong> 语句</td><td>整个连接/存储过程</td><td>整个批次/存储过程</td></tr><tr><td>能建索引</td><td>❌</td><td>✅</td><td>有限（只有主键/唯一约束）</td></tr><tr><td>物化（先算好存起来）</td><td>❌ 每次引用都重算</td><td>✅</td><td>✅</td></tr><tr><td>适合</td><td>一次性取数、递归</td><td>大量中间数据、多次使用</td><td>小量数据、简单传递</td></tr></tbody></table><p><strong>关键点</strong>：CTE 不会把结果存起来。如果你在后面的查询里引用了同一个 CTE 两次，它会算两遍。数据量大的话，用临时表先存一下再用。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- CTE 引用两次 = 算两遍</span></span>
<span class="line"><span style="color:#ABB2BF;">;</span><span style="color:#C678DD;">WITH</span><span style="color:#ABB2BF;"> cte </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> (</span><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> ... 一个很重的查询 ...)</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> cte a </span><span style="color:#C678DD;">JOIN</span><span style="color:#ABB2BF;"> cte b </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> a</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Id</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> b</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ParentId</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 这里 cte 被执行了两次！</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 改成临时表：只算一次</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> ... 一个很重的查询 ...</span></span>
<span class="line"><span style="color:#C678DD;">INTO</span><span style="color:#ABB2BF;"> #temp;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> #temp a </span><span style="color:#C678DD;">JOIN</span><span style="color:#ABB2BF;"> #temp b </span><span style="color:#C678DD;">ON</span><span style="color:#D19A66;"> a</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">Id</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> b</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">ParentId</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="几个注意的点" tabindex="-1"><a class="header-anchor" href="#几个注意的点"><span>几个注意的点</span></a></h2><ol><li>CTE 后面必须紧跟一条 SELECT/INSERT/UPDATE/DELETE/MERGE，不能跟其他东西</li><li>CTE 里不能用 ORDER BY（除非配合 TOP/OFFSET-FETCH）</li><li>递归 CTE 的递归部分不能用 TOP、DISTINCT、GROUP BY、HAVING</li><li>递归 CTE 里只能有一个 UNION ALL（锚点和递归之间），不能是 UNION</li><li>同一个 WITH 里的多个 CTE，后面的可以引用前面的，但不能反过来</li></ol>`,53)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};